-- GENERATED by `pnpm gen:catalog` from packages/template-engine + packages/country-rules. DO NOT EDIT BY HAND.
-- Templates are published (all 105 render in tests). Country rules stay 'draft' until a human review marks them reviewed.

on conflict (id) do update set name = excluded.name, category = excluded.category, supports_rtl = excluded.supports_rtl,
  supports_docx = excluded.supports_docx, is_premium = excluded.is_premium;

on conflict (template_id, version_no) do update set spec = excluded.spec;

on conflict (country_code) do update set name = excluded.name, config = excluded.config, last_reviewed_on = excluded.last_reviewed_on;

delete from public.country_rule_sources where country_code in (select country_code from public.country_rules);
